import { escape, icon, button, rating } from "./components.js";
import { resultSummary } from "./session.js";
import { labView } from "./labs.js";

export function shell(content, ui, session, lesson, history) {
  return `<aside class="sidebar"><a href="#" class="brand" data-action="home"><span>${icon("book")}</span>ExplainBack<i>✳</i></a><span class="workspace-label">THE UNDERSTANDING WORKBENCH</span><nav aria-label="Main navigation">${[
    ["practice", "book", "Practice studio"],
    ["history", "chart", "Learning cards"],
    ["about", "spark", "How it works"],
  ]
    .map(
      ([id, glyph, label]) =>
        `<button class="nav-item ${ui.page === id ? "active" : ""}" data-action="nav" data-page="${id}" ${ui.page === id ? 'aria-current="page"' : ""}>${icon(glyph)}${label}${id === "history" ? `<small>${history.length}</small>` : ""}</button>`,
    )
    .join(
      "",
    )}</nav>${session && !session.completed ? path(session, lesson) : `<div class="side-philosophy"><span>↗</span><p>A wrong answer is<br>a useful place<br>to start.</p><small>Bring a belief.<br>Leave with a reason.</small></div>`}<section class="connection"><div><span class="status-dot ${ui.available ? "online" : ""}"></span><b>${ui.checking ? "Finding your tutor" : ui.available ? "Local model ready" : "Guided mode ready"}</b></div><p>${ui.available ? "GPT-OSS 20B · on this computer" : "Reviewed explanations always available."}</p><button class="text-button" data-action="reconnect" data-testid="reconnect-ai" ${ui.checking ? "disabled" : ""}>${icon("refresh")}${ui.checking ? "Checking…" : "Check AI connection"}</button></section><div class="sidebar-footer">BUHACK 2.0 <span>EDTECH / 2026</span></div></aside><div class="app-content"><header class="topbar"><div><span>Your studio</span><i>/</i><b>${session && !session.completed && ui.page === "practice" ? escape(lesson.title) : ui.page === "history" ? "Learning cards" : ui.page === "about" ? "Our approach" : "Make understanding visible"}</b></div><span class="mode-badge">${icon(session?.mode === "local-ai" ? "spark" : "book")}${session?.mode === "local-ai" ? "Local AI coaching" : ui.available && ui.mode === "local-ai" ? "Local AI available" : "Reviewed lesson mode"}</span></header><main id="main" tabindex="-1"><div id="storage-warning" class="notice warning" role="status" ${ui.storageWarning ? "" : "hidden"}>${escape(ui.storageWarning)}</div>${ui.restored ? `<div class="notice" role="status">${icon("check")}<span>Your draft is restored. You can pick up where you left off.</span><button data-action="dismiss-restored" aria-label="Dismiss draft notice">${icon("close")}</button></div>` : ""}${content}</main><footer class="page-footer"><span>Understanding, one good question at a time.</span><span>${icon("shield")} No account. No cloud model. Your work stays here.</span></footer></div>`;
}

function path(session, lesson) {
  return `<section class="side-path"><span class="overline">YOUR SESSION</span><h3>${escape(lesson.title)}</h3><ol><li class="${session.phase === "belief" ? "current" : "done"}"><span>${session.phase === "belief" ? "01" : "✓"}</span>Capture a belief</li>${lesson.steps.map((step, index) => `<li class="${index === session.step && ["answer", "review"].includes(session.phase) ? "current" : session.responses[index].checked ? "done" : ""}"><span>${session.responses[index].checked ? "✓" : `0${index + 2}`}</span>${escape(step.title)}</li>`).join("")}<li class="${["transfer", "summary"].includes(session.phase) ? "current" : ""}"><span>05</span>Prove it somewhere new</li></ol></section>`;
}

export function home(ui, lessons, session) {
  return `<div class="home-heading"><span class="overline">LESS CONFIDENT GUESSING. MORE “OH, I GET IT.”</span><h1>Know it?<br><em>Show why.</em><span class="heading-star">✳</span></h1><p>Teach a concept. Find the shaky bit.<br>Rebuild it with a reason you can actually use.</p></div><section class="belief-preview" aria-label="An example learning journey"><span class="overline">A BELIEF WORTH TESTING</span><div class="belief-example"><span class="example-tag">BEFORE</span><p>“A stiffer material<br>must be stronger.”</p><div class="example-divider">${icon("arrow")} ONE GOOD QUESTION LATER</div><span class="example-tag after">AFTER</span><p>“Stiffness is the slope.<br>Strength is a different limit.”</p></div><div class="example-caption">An example from the mechanics lesson.</div></section><div class="section-heading"><div><span class="overline">01 / CHOOSE YOUR QUESTION</span><h2>What do you want to make click?</h2></div><span class="small-note">Three focused lessons · about 6–10 minutes</span></div><div class="lesson-grid">${lessons.map((lesson, index) => `<button class="lesson-card ${ui.selected === lesson.id ? "selected" : ""}" data-action="select-lesson" data-value="${lesson.id}" data-testid="lesson-${lesson.id}" aria-pressed="${ui.selected === lesson.id}"><div class="lesson-card-top"><span class="lesson-glyph tone-${index}">${lesson.symbol}</span><span class="selection-circle">${ui.selected === lesson.id ? "✓" : ""}</span></div><span class="overline">${lesson.subject}</span><h3>${lesson.title}</h3><p>${lesson.short}</p><span class="lesson-card-footer">3 ideas to test ${icon("arrow")}</span></button>`).join("")}</div><section class="start-panel"><div><span class="overline">02 / CHOOSE YOUR COACH</span><h2>Local intelligence. Clear explanations.</h2><p>AI responds to your words. Reviewed answers keep the lesson moving.</p></div><div class="mode-options" role="group" aria-label="Choose a coaching mode"><button data-action="mode" data-value="local-ai" data-testid="mode-ai" aria-pressed="${ui.mode === "local-ai"}" ${!ui.available ? "disabled" : ""}>${icon("spark")}<span><b>Local AI</b><small>${ui.available ? "GPT-OSS 20B is connected" : "Connect the local tutor first"}</small></span></button><button data-action="mode" data-value="reviewed" data-testid="mode-reviewed" aria-pressed="${ui.mode === "reviewed"}">${icon("book")}<span><b>Guided demo</b><small>Reviewed answers. No model needed.</small></span></button></div></section><div class="start-actions"><p>${icon("shield")} No marks, no pressure. Just a better explanation.</p>${button(session && !session.completed ? "Continue my session" : "Enter the practice studio", session && !session.completed ? "resume" : "start", { arrow: true, testid: "start-session" })}</div>${session && !session.completed ? '<button class="text-button" data-action="new-session">Start a different lesson instead</button>' : ""}<div class="method-strip"><b>THE EXPLAINBACK LOOP</b><span>Believe</span><i>→</i><span>Test</span><i>→</i><span>Rebuild</span><i>→</i><span>Apply</span></div>`;
}

export function beliefView(session, lesson) {
  return `<div class="session-heading"><span class="overline">START WITH A BELIEF, NOT A PERFECT ANSWER</span><h1>What’s your take?</h1><p>${escape(lesson.intro)}</p></div><div class="two-column"><section class="surface"><div class="pip-intro"><span class="pip-face">✳</span><div><b>Pip, your curious classmate</b><p>Explain it like we’re studying together. What happens, why, and can you give an example?</p></div></div><form id="belief-form"><label for="belief-input">Your first explanation</label><textarea id="belief-input" data-testid="belief-input" name="belief" minlength="20" maxlength="4000" required placeholder="Here’s what I think happens, and why…">${escape(session.belief)}</textarea><div class="field-meta"><span>At least 20 characters. Being unsure is welcome.</span><span id="belief-count">${session.belief.length}/4000</span></div>${rating("How confident do you feel?", session.confidence, "confidence")}<div class="form-footer"><button class="text-button" type="button" data-action="sample">Try a sample misconception</button><button class="button primary" data-testid="begin-practice" type="submit">Let’s test my thinking ${icon("arrow")}</button></div></form></section><aside class="session-note"><span class="note-icon">↗</span><h2>You will get answers.</h2><p>After every response, you’ll see the correct explanation, a worked example, and a quick way to check the idea.</p><ol><li>Explain one idea.</li><li>See what holds up.</li><li>Try the counterexample lab.</li><li>Apply it to a new case.</li></ol><div class="note-bottom">${icon("leaf")} The interesting part is what changes.</div></aside></div>`;
}

export function answerView(session, lesson) {
  const index = session.step,
    step = lesson.steps[index],
    response = session.responses[index];
  return `${sessionHeader(index, step.title)}<div class="two-column"><section class="surface"><div class="question-block"><span class="pip-face small">✳</span><div><span class="overline">PIP’S QUESTION · ${index + 1} OF 3</span><h2>${escape(lesson.questions[index])}</h2></div></div><form id="answer-form"><label for="answer-input">Explain your reasoning</label><textarea id="answer-input" data-testid="answer-input" name="answer" minlength="10" maxlength="2000" required placeholder="I think… because…">${escape(response.answer)}</textarea><div class="field-meta"><span>A sentence is enough to start. At least 10 characters.</span><span id="answer-count">${response.answer.length}/2000</span></div><details class="hint"><summary>Give me a small hint</summary><p>${escape(step.hint)}</p></details><div class="form-footer"><span class="save-status">${icon("shield")} Draft kept on this tab</span><button class="button primary" type="submit" data-testid="submit-answer">${session.mode === "local-ai" ? "Ask Pip & see the explanation" : "See the explanation"} ${icon("arrow")}</button></div></form></section>${reference(lesson, index, session)}</div>`;
}

export function reviewView(session, lesson, ui) {
  const index = session.step,
    step = lesson.steps[index],
    response = session.responses[index],
    feedback = response.feedback;
  const labels = {
    supported: "Your reasoning holds up",
    partial: "There’s a useful piece here",
    revisit: "Here’s the idea to rebuild",
  };
  return `${sessionHeader(index, step.title)}<div class="review-layout"><div class="review-main"><section class="feedback-card ${feedback?.verdict || ""}" data-testid="feedback-card" aria-live="polite"><div class="feedback-title"><span class="pip-face small">✳</span><div><span class="overline">${feedback?.source === "local-ai" ? "PIP’S LOCAL AI FEEDBACK" : "YOUR LEARNING CHECK-IN"}</span><h2>${ui.busy ? "Pip is looking at your reasoning…" : feedback ? labels[feedback.verdict] || "Let’s look at the idea" : "The reviewed explanation is ready."}</h2></div></div>${ui.busy ? `<p>The explanation below is ready now. You can keep learning while Pip responds.</p><div class="request-status"><span class="spinner"></span><span id="request-time">${ui.elapsed}s elapsed</span><button class="text-button" data-action="skip-ai" data-testid="skip-ai">Continue without waiting</button></div>` : feedback ? `<p>${escape(feedback.feedback)}</p>${feedback.quote ? `<blockquote>“${escape(feedback.quote)}”<cite>From the ${response.feedbackForRevision ? "rewrite" : "answer"} sent to Pip for question ${index + 1} · quote located, interpretation can still be wrong</cite></blockquote>${response.feedbackAnswer ? `<details class="reviewed-snapshot"><summary>Text reviewed by Pip</summary><p>${escape(response.feedbackAnswer)}</p></details>` : ""}` : ""}` : "<p>Compare your explanation with the reasoning below, then try the quick check. There is no AI grade.</p>"}${feedback?.warning ? `<p class="feedback-warning">${icon("shield")}${escape(feedback.warning)}</p>` : ""}${ui.error ? `<div class="inline-error" role="alert"><p>${escape(ui.error)} Your answer is kept. You can use the reviewed explanation below.</p>${button("Try Pip again", "retry-feedback", { secondary: true, testid: "feedback-retry" })}</div>` : ""}${session.mode === "local-ai" && !ui.busy && !feedback && !ui.error ? '<p class="small-note">Live feedback was skipped. This explanation is from the prepared lesson.</p>' : ""}</section><section class="surface teaching" data-testid="canonical-answer"><div class="section-kicker">${icon("book")} WHAT ACTUALLY HAPPENS</div><h2>The idea, made clear.</h2><p class="canonical">${escape(step.answer)}</p><h3>Why this works</h3><p>${escape(step.why)}</p><div class="worked-example"><span class="overline">A CONCRETE EXAMPLE</span><p>${escape(step.workedExample)}</p></div><details class="misconception"><summary>The trap to watch for</summary><p>${escape(step.misconception)}</p></details><span class="source-reference">Reviewed lesson ${index + 1} · ${escape(lesson.notes[index].title)}</span></section><section class="surface quick-check"><span class="overline">MAKE THE REASONING YOURS</span><h2>One quick check.</h2><p class="check-question">${escape(step.checkpoint.question)}</p>${options(step.checkpoint.options, response.choice, response.checked, step.checkpoint.answer, "checkpoint")}<div class="check-actions">${!response.checked ? button("Check my understanding", "check-understanding", { testid: "check-understanding", disabled: response.choice === null }) : checkResult(response.choice === step.checkpoint.answer, step.checkpoint.explanation)}</div></section><section class="surface rebuild"><details ${response.revising ? "open" : ""}><summary>Put it into your own words again <span>Optional, but useful</span></summary><form id="revision-form"><label for="revision-input">What would you say differently now?</label><textarea id="revision-input" name="revision" minlength="10" maxlength="2000" placeholder="I used to think… Now I understand…">${escape(response.revision)}</textarea><div class="form-footer"><span class="small-note">${response.attempt < 3 ? "Your first answer stays in your learning card." : "You’ve used the three local reviews for this idea."}</span>${session.mode === "local-ai" && response.attempt < 3 ? `<button class="button secondary" type="submit" ${ui.busy ? "disabled" : ""}>Review my rewrite ${icon("spark")}</button>` : button("Keep this rewrite", "save-revision", { secondary: true })}</div></form></details></section><div class="next-actions"><p>${response.checked ? "You’ve seen the explanation. Take the next step." : "Complete the quick check to continue. A wrong answer is useful too."}</p>${button(index === 2 ? "Apply it somewhere new" : "Next idea", "next-step", { arrow: true, testid: "next-step", disabled: !response.checked })}</div></div><aside><section class="surface lab" data-testid="prediction-lab">${labView(lesson.id, index, ui.lab)}</section><section class="your-answer"><span class="overline">YOUR FIRST TAKE</span><p>“${escape(response.answer)}”</p><button class="text-button" data-action="edit-answer">${icon("back")} Edit my answer</button></section><div class="review-tip">${icon("leaf")} A correct option is a check, not proof of mastery. The reason matters.</div></aside></div>`;
}

function sessionHeader(index, title) {
  return `<div class="session-topline"><button class="text-button" data-action="back-studio">${icon("back")} Back to studio · keep my draft</button><span>IDEA ${index + 1} / 3</span></div><div class="session-heading compact"><span class="overline">TEST → UNDERSTAND → REBUILD</span><h1>${escape(title)}</h1></div>`;
}
function reference(lesson, index, session) {
  return `<aside class="reference"><span class="overline">A REFERENCE, NOT A SCRIPT</span><h2>Your lesson notebook</h2>${lesson.notes.map((note, i) => `<details ${i === index ? "open" : ""}><summary><span>0${i + 1}</span>${escape(note.title)}</summary><p>${escape(note.text)}</p></details>`).join("")}<details class="first-belief"><summary>What I said at the start</summary><p>${escape(session.belief)}</p></details><p class="small-note">Your answer and the relevant note go to GPT-OSS on this computer in local AI mode. The model has no file or terminal access.</p></aside>`;
}
function options(items, choice, checked, correct, prefix) {
  return `<div class="answer-options" role="group" aria-label="Choose one answer">${items.map((item, index) => `<button data-action="${prefix}-option" data-value="${index}" data-testid="${prefix}-option-${index}" aria-pressed="${choice === index}" class="${choice === index ? "selected" : ""} ${checked && index === correct ? "correct" : ""} ${checked && choice === index && index !== correct ? "incorrect" : ""}" ${checked ? "disabled" : ""}><span>${String.fromCharCode(65 + index)}</span>${escape(item)}${checked && index === correct ? icon("check") : ""}</button>`).join("")}</div>`;
}
function checkResult(correct, explanation) {
  return `<div class="check-result ${correct ? "success" : "learn"}" role="status"><b>${correct ? "Yes. That’s the reasoning." : "A useful correction."}</b><p>${escape(explanation)}</p></div>`;
}
export function transferView(session, lesson) {
  const transfer = lesson.transfer;
  return `<div class="session-topline"><button class="text-button" data-action="back-studio">${icon("back")} Back to studio · keep my draft</button><span>THE TRANSFER CHECK</span></div><div class="session-heading"><span class="overline">SAME IDEA. DIFFERENT SITUATION.</span><h1>Does it travel?</h1><p>Try applying the idea without copying the example you just saw.</p></div><section class="surface transfer-card"><span class="overline">${escape(lesson.subject)} / A NEW CASE</span><h2>${escape(transfer.question)}</h2>${options(transfer.options, session.transferChoice, session.transferChecked, transfer.answer, "transfer")}${session.transferChecked ? checkResult(session.transferChoice === transfer.answer, transfer.explanation) : ""}<div class="form-footer">${session.transferChecked ? `${rating("How confident do you feel now?", session.finalConfidence, "final-confidence")}${button("Make my learning card", "finish-session", { arrow: true, testid: "finish-session" })}` : button("Check my answer", "check-transfer", { testid: "check-transfer", disabled: session.transferChoice === null })}</div></section>`;
}
export function summaryView(session, lesson) {
  const result = resultSummary(session, lesson);
  return `<section data-testid="summary"><div class="summary-heading"><span class="overline">A RECORD OF WHAT CHANGED</span><h1>A belief, rebuilt.</h1><p>You did more than answer questions. You met an explanation, tested it, and made it your own.</p></div><div class="summary-metrics"><div><span>Confidence · your own rating</span><b>${session.confidence}<i>→</i>${session.finalConfidence}<small> / 5</small></b></div><div><span>Quick checks</span><b>${result.passed}<small> / 3 correct</small></b></div><div><span>Transfer to a new case</span><b class="transfer-outcome">${result.transferPassed ? "Applied ✓" : "Worth revisiting ↗"}</b></div></div><article class="learning-card"><div class="learning-card-heading"><span class="brand-mini">${icon("book")} ExplainBack</span><span>${escape(lesson.title)}</span></div><span class="overline">WHAT I THOUGHT</span><blockquote>${escape(session.belief)}</blockquote><div class="learning-card-divider">THREE IDEAS, MADE CLEARER</div>${result.checks.map((check, index) => `<div class="learning-card-row"><span class="card-number">0${index + 1}</span><div><h3>${escape(check.title)}</h3><p>${escape(lesson.steps[index].answer)}</p>${check.revision ? `<div class="my-rewrite"><b>My rewrite</b><p>${escape(check.revision)}</p></div>` : ""}<small>${check.passed ? "Quick check answered correctly" : "Quick check explanation reviewed"}</small></div></div>`).join("")}<div class="learning-card-bottom">${session.mode === "local-ai" ? "Local AI coaching + reviewed explanations" : "Reviewed lesson mode"} · A learning record, not a grade.</div></article><div class="summary-save ${session.persisted ? "" : "unsaved"}" role="status">${icon("shield")}${session.persisted ? "Learning card saved on this browser." : "This card is not saved to browser storage. Download it to keep a copy."}</div><div class="summary-actions">${button("Download my learning card", "download", { secondary: true })}${!session.persisted ? button("Retry saving", "retry-save", { secondary: true }) : ""}${button("Explore another concept", "finish", { arrow: true })}</div></section>`;
}

export function historyView(history) {
  return `<div class="session-heading"><span class="overline">SMALL CHANGES, MADE VISIBLE</span><h1>Your learning cards.</h1><p>Completed sessions saved on this browser. Your answers are never uploaded to a cloud account.</p></div>${history.length ? `<div class="history-list">${history.map((item) => `<article class="surface history-row"><span class="history-glyph">${icon("leaf")}</span><div><span class="overline">${escape(new Date(item.date).toLocaleDateString(undefined, { month: "short", day: "numeric" }))}</span><h2>${escape(item.title)}</h2><p>${item.passed}/3 quick checks · Transfer ${item.transferPassed ? "applied" : "reviewed"} · Confidence ${item.confidence} → ${item.finalConfidence}</p></div><span class="history-mode">${item.persisted === false ? "Not saved" : item.mode === "local-ai" ? "Local AI" : "Guided"}</span>${item.session ? `<button class="text-button" data-action="open-card" data-value="${escape(item.id)}">Open card ${icon("arrow")}</button>` : ""}</article>`).join("")}</div><button class="text-button" data-action="clear-history">Clear saved learning cards</button>` : `<section class="surface empty-state">${icon("leaf")}<h2>Your next “oh, I get it” belongs here.</h2><p>Complete a lesson and keep a record of what changed.</p>${button("Choose a lesson", "home", { arrow: true })}</section>`}`;
}
export function aboutView() {
  return `<div class="session-heading"><span class="overline">EXPLAINBACK / THE IDEA</span><h1>Make the gap useful.</h1><p>Familiarity can feel like understanding. ExplainBack gives that feeling a small, concrete test.</p></div><div class="about-grid">${[
    [
      "01",
      "Capture a belief",
      "Write what you think and how confident you feel. No need to get it right first.",
    ],
    [
      "02",
      "Meet a counterexample",
      "Answer a focused question. Explore a small lab that makes the relationship visible.",
    ],
    [
      "03",
      "Get the explanation",
      "Every answer leads to a reviewed explanation and worked example. Local AI adds feedback on your words.",
    ],
    [
      "04",
      "Prove it somewhere new",
      "Apply the idea to another case, then keep a learning card of what changed.",
    ],
  ]
    .map(
      ([number, title, text]) =>
        `<article class="surface"><span class="about-number">${number}</span><h2>${title}</h2><p>${text}</p></article>`,
    )
    .join(
      "",
    )}</div><section class="surface honesty"><h2>Clear about what Pip can do.</h2><p>GPT-OSS 20B runs through Ollama on your computer. It can misinterpret reasoning. A quote located in your answer is not proof that the AI’s judgement is correct. Reviewed lesson explanations and the authored quick checks are separate from the model.</p><p>The hosted static demo uses reviewed lessons. Local AI needs this app’s local server and Ollama. No tunnel, external model, terminal tools, or file access is used by Pip.</p><p>Drafts stay in this tab’s session storage. Completed learning cards, including your explanations, stay in this browser’s local storage when it is available. Save failures are shown; you can download a text copy.</p></section>`;
}
